async function refreshPublishedEvents(force=false){
 const key='fighteye-events-last-check', last=Number(localStorage.getItem(key)||0);
 if(!force&&Date.now()-last<7*86400000)return;
 try{
  const response=await fetch('data/events-api.json?t='+Date.now(),{cache:'no-store'});
  if(!response.ok)throw new Error('Event data unavailable');
  const rows=await response.json();
  if(!Array.isArray(rows)||rows.length<events.length-state.adminEvents.length||new Set(rows.map(e=>e.id)).size!==rows.length||rows.some(e=>!e.id||!e.start||!e.end||e.start>e.end))throw new Error('Invalid event data');
  const local=state.adminEvents.filter(e=>!rows.some(x=>x.id===e.id));
  events.splice(0,events.length,...rows.map(e=>({...e,status:statusFor(e)})),...local.map(e=>({...e,status:statusFor(e)})));
  events.sort((a,b)=>new Date(a.start)-new Date(b.start));
  localStorage.setItem(key,String(Date.now()));
  state.eventRefresh='Checked '+new Date().toLocaleDateString('en-GB');
  render();
 }catch{state.eventRefresh='Offline data available';if(force)render();}
}
