function athleteWeights(id){return (state.weightRecords[id]||[]).slice().sort((a,b)=>a.date.localeCompare(b.date))}
function latestWeight(a){const rows=athleteWeights(a.id);return rows.length?`${rows[rows.length-1].kg.toFixed(1)} kg`:a.weight||'Not recorded'}
function parseHealthWeightXML(xml){const records=[],tag=/<Record\b[^>]*>/g;let match;while((match=tag.exec(xml))){const attrs={};for(const part of match[0].matchAll(/([A-Za-z]+)="([^"]*)"/g))attrs[part[1]]=part[2];if(attrs.type!=='HKQuantityTypeIdentifierBodyMass')continue;const date=(attrs.startDate||'').slice(0,10),value=Number(attrs.value),unit=(attrs.unit||'').toLowerCase(),kg=unit==='kg'?value:unit==='lb'||unit==='lbs'?value*0.45359237:unit==='st'?value*6.35029318:NaN;if(/^\d{4}-\d{2}-\d{2}$/.test(date)&&Number.isFinite(kg)&&kg>=10&&kg<=500)records.push({date,kg:Math.round(kg*10)/10,source:'Apple Health export'});if(records.length>10000)throw new Error('Too many weight samples in this file. Export a smaller date range.')}return records}
function weightPanel(a){const rows=athleteWeights(a.id),recent=rows.slice(-10).reverse(),values=rows.slice(-20),min=Math.min(...values.map(r=>r.kg)),max=Math.max(...values.map(r=>r.kg)),spread=Math.max(max-min,1),points=values.map((r,i)=>`${Math.round(i*280/Math.max(values.length-1,1))},${Math.round(70-(r.kg-min)*60/spread)}`).join(' ');return `<section class="weight-panel"><h4>Weight tracker</h4><p>Latest: <strong>${esc(latestWeight(a))}</strong></p>${values.length>1?`<svg class="weight-chart" viewBox="0 0 280 80" role="img" aria-label="Weight history from ${esc(values[0].date)} to ${esc(values[values.length-1].date)}"><polyline points="${points}" fill="none" stroke="currentColor" stroke-width="3" stroke-linejoin="round"/></svg>`:''}<form class="weight-form" data-weight-form="${esc(a.id)}"><label>Date<input class="budget" name="date" type="date" required value="${new Date().toLocaleDateString('en-CA',{timeZone:'Europe/London'})}"></label><label>Weight (kg)<input class="budget" name="kg" type="number" min="10" max="500" step="0.1" required></label><button class="ghost" type="submit">Add weight</button></form>${recent.length?`<div class="weight-history">${recent.map(r=>`<div><span>${esc(r.date)} · ${r.kg.toFixed(1)} kg <small>${esc(r.source)}</small></span><button class="ghost" data-delete-weight="${esc(a.id)}" data-weight-date="${esc(r.date)}" aria-label="Remove weight for ${esc(r.date)}">Remove</button></div>`).join('')}</div>`:''}<label class="weight-import-label">Import Apple Health export.xml for this athlete<input type="file" accept=".xml,text/xml,application/xml" data-health-import="${esc(a.id)}"></label><small>On iPhone, export all Health data, unzip it in Files, then select export.xml. Only body mass entries are read. Import is manual; HealthKit automatic sync requires a native iOS app. Data stays in this browser.</small>${state.weightError?`<p role="alert">${esc(state.weightError)}</p>`:''}</section>`}
function statusFor(e){const n=new Date(),start=new Date(e.start+'T00:00:00'),end=new Date(e.end+'T23:59:59');if(e.kind){if(n>end)return'Past '+e.kind.toLowerCase();if(n>=start)return'Happening today';return e.access||'Scheduled';}if(n>=start&&n<=end)return'Competition Live';if(n>end)return e.resultsUrl?'Results Available':'Past event';if(!e.closing)return'Date confirmed • entry TBC';const closing=new Date(e.closing+'T23:59:59');if(n>closing)return'Registration Closed';return Math.ceil((closing-n)/86400000)<=14?'Closing Soon':'Registration Open';}
