function settingsView(){return `<section class="section"><div class="section-head"><div><h2>Settings</h2><small>Calendar connections</small></div></div><section class="panel icloud-connect"><div><h3>iCloud calendar connection</h3><p>Subscribe to the full FightEye calendar. Published event changes will appear in your read-only iCloud subscription when Calendar refreshes.</p><small>On iPhone: Calendar → Calendars → Add Calendar → Add Subscription Calendar. Paste the feed link and choose iCloud as the account.</small></div><div class="icloud-actions"><a class="button" href="${ICLOUD_FEED.replace(/^https:/,'webcal:')}">Subscribe in Calendar</a><button class="ghost" id="copyCalendarFeed">Copy feed link</button></div></section></section>`;}
function athleteProfileForm(a){return state.editAthlete===a.id?`<form class="club-form athlete-edit" data-athlete-form="${esc(a.id)}"><label>Name<input class="budget" name="name" required maxlength="80" value="${esc(a.name)}"></label><label>Competition category<input class="budget" name="category" maxlength="80" value="${esc(a.category||'')}"></label><label>Ranking / division<input class="budget" name="ranking" maxlength="80" value="${esc(a.ranking||'')}"></label><label>Weight<input class="budget" name="weight" maxlength="30" value="${esc(a.weight||'')}"></label><label>Licence<input class="budget" name="licence" maxlength="60" value="${esc(a.licence||'')}"></label><label>Photo or avatar (PNG, JPEG or WebP, up to 4 MB)<input class="budget" name="photo" type="file" accept="image/png,image/jpeg,image/webp"></label>${athletePhoto(a)?'<label><input type="checkbox" name="removePhoto"> Remove current photo</label>':''}<fieldset class="profile-membership"><legend>Clubs and national teams</legend>${state.groups.map(g=>`<label><input type="checkbox" name="groups" value="${esc(g.id)}" ${(g.memberIds||[]).includes(a.id)?'checked':''}> ${esc(g.name)}</label>`).join('')}</fieldset><fieldset class="profile-emergency"><legend>Emergency contact • stored on this device</legend><label>Name<input class="budget" name="emergencyName" maxlength="80" value="${esc(a.emergencyName||'')}"></label><label>Phone<input class="budget" name="emergencyPhone" type="tel" maxlength="40" value="${esc(a.emergencyPhone||'')}"></label></fieldset>${state.athleteEditError?`<p role="alert">${esc(state.athleteEditError)}</p>`:''}<button class="button" type="submit">Save athlete profile</button></form>`:''}
function annualResults(a){const records=Array.isArray(a.annualResults)?a.annualResults:[];return `<section class="annual-results"><h4>Year record by organisation</h4>${records.length?`<div class="annual-list">${[...records].sort((x,y)=>y.year-x.year||x.organisation.localeCompare(y.organisation)).map(r=>`<div class="annual-row"><div><strong>${esc(r.year)} • ${esc(r.organisation)}</strong><span>🥇 ${Number(r.gold)||0} · 🥈 ${Number(r.silver)||0} · 🥉 ${Number(r.bronze)||0}</span></div><button class="ghost" data-delete-result="${esc(a.id)}" data-year="${esc(r.year)}" data-organisation="${esc(r.organisation)}" aria-label="Remove ${esc(r.year)} ${esc(r.organisation)} record">Remove</button></div>`).join('')}</div>`:'<p class="muted">No annual results recorded yet.</p>'}<form class="annual-form" data-result-form="${esc(a.id)}"><label>Year<input class="budget" name="year" type="number" min="2000" max="2100" required value="${new Date().getFullYear()}"></label><label>Organisation<input class="budget" name="organisation" required maxlength="60" list="org-${esc(a.id)}" placeholder="e.g. WAKO"></label><datalist id="org-${esc(a.id)}">${['WAKO','WKU','ICO','ISKA','WKKC','WKC','GB Grand Slam','Other'].map(o=>`<option value="${esc(o)}">`).join('')}</datalist><label>Gold<input class="budget" name="gold" type="number" min="0" max="999" required value="0"></label><label>Silver<input class="budget" name="silver" type="number" min="0" max="999" required value="0"></label><label>Bronze<input class="budget" name="bronze" type="number" min="0" max="999" required value="0"></label><button class="ghost" type="submit">Save year record</button></form><small>Saving the same year and organisation updates its totals.</small></section>`}
function passportView(){return `<section class="section"><div class="section-head"><div><h2>Athlete Passport</h2><small>Digital documents and competition readiness</small></div></div><div class="grid">${athletes.map(a=>`<article class="panel athlete">${athletePhoto(a)?`<img class="avatar athlete-photo" src="${esc(a.photo)}" alt="${esc(a.name)}">`:`<div class="avatar">${esc(a.flag||'🥋')}</div>`}<h3>${esc(a.name)}</h3><p>${esc(a.category||a.ranking||'Category to be confirmed')}</p><p class="muted">${state.groups.filter(g=>(g.memberIds||[]).includes(a.id)).map(g=>esc(g.name)).join(' • ')||'No club or team linked'}</p><div class="check-grid"><span>Licence <b>${esc(a.licence)}</b></span><span>Insurance <b>${esc(a.insurance)}</b></span><span>Weight <b>${esc(latestWeight(a))}</b></span><span>Passport <b>${esc(a.passport)}</b></span><span>Medical <b>${esc(a.medical)}</b></span><span>Record <b>${esc(a.record)}</b></span></div><button class="ghost" data-edit-athlete="${esc(a.id)}">Edit profile</button>${athleteProfileForm(a)}${annualResults(a)}${weightPanel(a)}<button class="button" data-pass="${esc(a.id)}">Open QR pass</button></article>`).join('')}</div></section>`;}
function travelView(){const total=Object.values(state.budget).reduce((a,b)=>a+Number(b),0);const e=events.find(x=>state.saved.has(x.id))||events[0];return `<section class="section"><div class="section-head"><div><h2>Travel & Budget Centre</h2><small>Itineraries, costs and packing</small></div></div><div class="grid"><div class="panel"><h3>${esc(e.flag)} ${esc(e.name)}</h3><p>${esc(e.travel)} • ${esc(e.hotel)}</p><p>${fmt(e.start)}–${fmt(e.end)}</p><button class="button" data-open="${esc(e.id)}">Open itinerary</button></div><div class="panel"><h3>Budget planner</h3>${Object.entries(state.budget).map(([k,v])=>`<label>${k[0].toUpperCase()+k.slice(1)} <input class="budget" data-budget="${k}" type="number" min="0" value="${v}"></label>`).join('')}<div class="budget-total">Estimated total <strong>£${total}</strong></div></div><div class="panel"><h3>Packing checklist</h3>${['Passport/licence','Uniform','Gloves and footpads','Water and food','Chargers','Medication'].map((x,i)=>`<label class="task"><input type="checkbox" ${i<2?'checked':''}> ${x}</label>`).join('')}</div></div></section>`;}
function clubView(){
 const group=state.groups.find(g=>g.id===state.selectedGroup)||state.groups[0];
 const members=athletes.filter(a=>(group.memberIds||[]).includes(a.id));
 const available=athletes.filter(a=>!(group.memberIds||[]).includes(a.id));
 const website=clubWebsite(group.website||''),email=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(group.email||'')?group.email:'',phone=String(group.phone||'').replace(/[^+\d]/g,'');
 return `<section class="section club-os"><div class="section-head"><div><h2>ClubOS</h2><small>Manage clubs and national fight teams on this device</small></div></div>
 <div class="club-switch" role="group" aria-label="Clubs and teams">${state.groups.map(g=>`<button class="chip ${g.id===group.id?'active':''}" data-group="${esc(g.id)}">${g.kind==='national'?'🌍':'🥋'} ${esc(g.name)}</button>`).join('')}</div>
 <div class="club-tools"><button class="button" data-club-form="athlete">Add athlete</button><button class="ghost" data-club-form="group">Add club or national team</button><button class="ghost" data-club-form="injury">🩹 Injury tracker</button></div>
 ${state.clubForm==='group'?`<form class="panel club-form" id="groupForm"><h3>Add club or national team</h3><label>Name<input class="budget" name="name" required maxlength="80" placeholder="Team name"></label><label>Type<select class="budget" name="kind"><option value="club">Club</option><option value="national">National fight team</option></select></label><label>Country<input class="budget" name="country" required maxlength="60" placeholder="Country"></label><button class="button" type="submit">Create team</button></form>`:''}
 ${state.clubForm==='athlete'?`<form class="panel club-form" id="athleteForm"><h3>Add athlete to ${esc(group.name)}</h3><label>Name<input class="budget" name="name" required maxlength="80" placeholder="Athlete name"></label><label>Category / ranking<input class="budget" name="ranking" maxlength="80" placeholder="e.g. Older cadet −42kg PF"></label><label>Weight<input class="budget" name="weight" maxlength="30" placeholder="e.g. 42 kg"></label><button class="button" type="submit">Save athlete</button></form>`:''}
 ${state.clubForm==='details'?`<form class="panel club-form" id="clubDetailsForm"><h3>Edit ${esc(group.name)}</h3><label>Club or team name<input class="budget" name="name" required maxlength="80" value="${esc(group.name)}"></label><label>Country<input class="budget" name="country" maxlength="60" value="${esc(group.country||'')}"></label><label>Logo (PNG, JPEG or WebP, up to 4 MB)<input class="budget" name="logo" type="file" accept="image/png,image/jpeg,image/webp"></label>${clubLogo(group)?'<label><input type="checkbox" name="removeLogo"> Remove current logo</label>':''}<label>Email<input class="budget" name="email" type="email" maxlength="120" value="${esc(group.email||'')}"></label><label>Phone<input class="budget" name="phone" type="tel" maxlength="40" value="${esc(group.phone||'')}"></label><label>Website (https://)<input class="budget" name="website" type="url" maxlength="200" value="${esc(group.website||'')}"></label><label>Address<textarea class="budget" name="address" maxlength="240" rows="2">${esc(group.address||'')}</textarea></label>${state.clubDetailsError?`<p role="alert">${esc(state.clubDetailsError)}</p>`:''}<button class="button" type="submit">Save club details</button></form>`:''}
 <div class="stats"><div class="stat"><strong>${members.length}</strong><span>${group.kind==='national'?'Team':'Club'} athletes</span></div><div class="stat"><strong>${state.groups.filter(g=>g.kind==='club').length}</strong><span>Clubs</span></div><div class="stat"><strong>${state.groups.filter(g=>g.kind==='national').length}</strong><span>National teams</span></div></div>
 <div class="panel club-summary club-title"><div class="club-identity">${clubLogo(group)?`<img class="club-logo" src="${esc(group.logo)}" alt="${esc(group.name)} logo">`:`<div class="club-logo club-logo-placeholder" aria-hidden="true">${esc(group.name.trim().split(/\s+/).slice(0,2).map(s=>s[0]||'').join('').toUpperCase())}</div>`}<div class="club-identity-copy"><h3>${esc(group.name)}</h3><p>${group.kind==='national'?'National fight team':'Club'} • ${esc(group.country||'Country not set')}</p><div class="club-contact">${email?`<a href="mailto:${esc(email)}">${esc(email)}</a>`:''}${phone?`<a href="tel:${esc(phone)}">${esc(group.phone)}</a>`:''}${website?`<a href="${esc(website)}" target="_blank" rel="noopener noreferrer">${esc(group.website)}</a>`:''}${group.address?`<span>${esc(group.address)}</span>`:''}${!email&&!phone&&!website&&!group.address?'<span>Contact details not added yet.</span>':''}</div></div></div><button class="ghost" data-club-form="details">Edit club details</button>${available.length?`<label>Add existing athlete<select id="linkAthlete" class="budget"><option value="">Select athlete</option>${available.map(a=>`<option value="${esc(a.id)}">${esc(a.name)}</option>`).join('')}</select></label>`:''}</div>
 <div class="grid">${members.length?members.map(a=>`<article class="panel"><div class="athlete-card-head">${athletePhoto(a)?`<img class="athlete-photo" src="${esc(a.photo)}" alt="${esc(a.name)}">`:`<span class="athlete-photo athlete-photo-placeholder" aria-hidden="true">${esc(a.name.trim().split(/\s+/).slice(0,2).map(part=>part[0]||'').join('').toUpperCase())}</span>`}<h3>${esc(a.name)}</h3></div><p>${esc(a.ranking||'Category to be confirmed')}</p><p>Weight: ${esc(latestWeight(a))}</p><p>Licence: ${esc(a.licence||'Not recorded')}</p><label class="task"><input type="checkbox" data-att="${esc(a.id)}" ${state.attendance[a.id]?'checked':''}> Attending tonight</label><button class="ghost club-remove" data-edit-athlete="${esc(a.id)}">Edit athlete</button>${athleteProfileForm(a)}${annualResults(a)}${weightPanel(a)}<button class="ghost club-remove" data-remove-member="${esc(a.id)}">Remove from this ${group.kind==='national'?'team':'club'}</button></article>`).join(''):'<div class="panel"><h3>No athletes yet</h3><p>Add an athlete or link an existing one above.</p></div>'}</div>
 ${injuryPanel(group,members)}
 <div class="panel club-summary"><h3>Team actions</h3><button class="button" id="teamExport">Export ${esc(group.name)} roster</button></div></section>`;
}
function moreView(){const modules=[['backend','🗄️','Backend Foundation','API health, persistence, security and deployment diagnostics'],['integrations','🔄','Integrations Engine','Source adapters, validation, deduplication and sync reports'],['analytics','🧠','AI & Analytics','Recommendations, projections and season intelligence'],['production','🚀','Production & DevOps','Monitoring, release checks and deployment readiness'],['sync','🔔','Smart Sync','Notifications, offline health and diagnostics'],['replay','🎬','Event Replay','Create post-event reports and media summaries'],['rankings','📈','Rankings Lab','Compare athletes and simulate ranking movement'],['parent','👨‍👩‍👧','Parent Companion','Family schedules, travel and live updates'],['admin','🛠️','Admin CMS','Add events, export data and validate records']];return `<section class="section"><div class="section-head"><div><h2>More tools</h2><small>Open a specialist FightEye module</small></div></div><div class="grid module-grid">${modules.map(m=>`<button class="panel module" data-tab="${m[0]}"><span>${m[1]}</span><h3>${m[2]}</h3><p>${m[3]}</p></button>`).join('')}</div></section>`;}
function syncView(){return `<section class="section"><div class="section-head"><div><h2>Smart Sync & Diagnostics</h2><small>Resilient background updates and data checks</small></div></div><div class="grid"><div class="panel"><h3>Notification rules</h3>${['Registration deadlines','Schedule changes','Opponent changes','Results available','Travel reminders'].map((x,i)=>`<label class="task"><input type="checkbox" ${i<4?'checked':''}> ${x}</label>`).join('')}</div><div class="panel"><h3>Sync health</h3><p>Event calendar: <b>Ready</b></p><p>Athlete passport: <b>Ready</b></p><p>Offline cache: <b>Ready</b></p><button class="button" id="syncNow">Sync now</button></div><div class="panel"><h3>Diagnostics</h3><p>Events: ${events.length}</p><p>Athletes: ${athletes.length}</p><p>Duplicate event IDs: ${duplicateIds(events)}</p><p>Invalid event records: ${invalidEvents().length}</p><button class="ghost" id="runTests">Run feature tests</button></div></div></section>`;}
function replayView(){const past=events.filter(e=>e.status==='Results Available');const display=past.length?past:events.slice(0,3);return `<section class="section"><div class="section-head"><div><h2>Event Replay & Media</h2><small>Phase 189 • turn competition data into a shareable report</small></div></div><div class="grid">${display.map((e,i)=>`<article class="panel replay-card"><div class="replay-thumb" style="--image:${esc(e.image)}"><span>▶</span></div><h3>${esc(e.name)}</h3><p>${fmt(e.start)} • ${esc(e.city)}</p><div class="medal-row"><span>🥇 ${i+1}</span><span>🥈 ${i}</span><span>🥉 ${i+2}</span></div><div class="actions"><button class="ghost" data-replay="${esc(e.id)}">Preview</button><button class="button" data-report="${esc(e.id)}">Download report</button></div></article>`).join('')}</div></section>`;}
function rankingsView(){const a=athletes[0];const projected=Math.max(1,7-(4-state.rankFinish));return `<section class="section"><div class="section-head"><div><h2>Rankings Lab</h2><small>Phase 190 • compare form and simulate outcomes</small></div></div><div class="grid"><div class="panel"><h3>${esc(a.name)} ranking simulator</h3><p>Current: <b>${esc(a.ranking)}</b></p><label>Projected finish: <b>${placement(state.rankFinish)}</b><input id="rankSlider" class="range" type="range" min="1" max="8" value="${state.rankFinish}"></label><div class="rank-result"><small>Estimated next ranking</small><strong>#${projected}</strong><span>${projected<7?'▲ likely improvement':'— limited movement'}</span></div></div><div class="panel"><h3>Athlete comparison</h3>${athletes.map((x,i)=>`<div class="compare-row"><span>${esc(x.flag)} ${esc(x.name)}</span><b>${esc(x.record)}</b><meter min="0" max="100" value="${82-i*8}"></meter></div>`).join('')}</div><div class="panel"><h3>Season intelligence</h3><p>Best opportunity: <b>GB Grand Slam 2</b></p><p>Highest difficulty: <b>WAKO Junior Worlds</b></p><p>Recommended load: <b>3 events in 8 weeks</b></p><button class="button" id="seasonExport">Export season plan</button></div></div></section>`;}
function parentView(){const a=athletes.find(x=>x.id===state.parentAthlete)||athletes[0];const next=events.find(e=>e.name===a.next)||events.find(e=>state.saved.has(e.id))||events[0];return `<section class="section"><div class="section-head"><div><h2>Parent Companion</h2><small>Phase 191 • simpler information for families</small></div><select id="parentAthlete" class="search source-select">${athletes.map(x=>`<option value="${esc(x.id)}" ${x.id===a.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="family-hero panel"><div class="avatar">${esc(a.flag)}</div><div><h3>${esc(a.name)}</h3><p>${esc(a.club)} • ${esc(a.weight)}</p></div><span class="status">Ready</span></div><div class="grid"><div class="panel"><h3>Next competition</h3><p><b>${esc(next.name)}</b></p><p>${fmt(next.start)} • ${esc(next.venue)}</p><p>${esc(next.travel)}</p><button class="button" data-open="${esc(next.id)}">Open event</button></div><div class="panel"><h3>Family updates</h3>${['Notify 60 minutes before fight','Notify when bracket changes','Notify when result is posted','Share estimated finish time'].map((x,i)=>`<label class="task"><input type="checkbox" ${i<3?'checked':''}> ${x}</label>`).join('')}</div><div class="panel"><h3>Weekend essentials</h3><p>Parking: <b>Venue car park</b></p><p>Weather: <b>${esc(next.weather)}</b></p><p>Emergency contact: <b>Coach team</b></p><button class="ghost" id="familyShare">Share family briefing</button></div></div></section>`;}
function adminView(){return `<section class="section"><div class="section-head"><div><h2>Admin CMS & Data Health</h2><small>Phase 192 • edit without touching code</small></div></div><div class="grid"><form class="panel" id="eventForm"><h3>Add local competition</h3><label>Name<input class="budget" name="name" required maxlength="80"></label><label>Organisation<input class="budget" name="org" required maxlength="40"></label><label>City<input class="budget" name="city" required maxlength="50"></label><label>Start date<input class="budget" name="start" type="date" required></label><label>Closing date<input class="budget" name="closing" type="date" required></label><button class="button" type="submit">Add event</button></form><div class="panel"><h3>Data health</h3><p>Events: <b>${events.length}</b></p><p>Custom events: <b>${state.adminEvents.length}</b></p><p>Duplicate IDs: <b>${duplicateIds(events)}</b></p><p>Invalid records: <b>${invalidEvents().length}</b></p><p>Placeholder registration links: <b>${events.filter(e=>e.registration==='#').length}</b></p><button class="ghost" id="validateLinks">Validate records</button></div><div class="panel"><h3>Data tools</h3><button class="button" id="exportData">Export JSON backup</button><button class="ghost" id="clearCustom">Remove custom events</button><p><small>Custom event changes are stored locally on this device.</small></p></div></div></section>`;}

function backendView(){return `<section class="section"><div class="section-head"><div><h2>Backend Foundation</h2><small>Phase 193 • API, persistence, security and deployment readiness</small></div></div><div class="stats"><div class="stat"><strong>${events.length}</strong><span>Event records</span></div><div class="stat"><strong>${athletes.length}</strong><span>Athlete records</span></div><div class="stat"><strong>${state.apiHealth==='Healthy'?'✓':'—'}</strong><span>API health</span></div><div class="stat"><strong>v1</strong><span>API version</span></div></div><div class="grid"><div class="panel"><h3>API health</h3><p>Status: <b>${esc(state.apiHealth)}</b></p><p>Endpoint: <code>/.netlify/functions/health</code></p><button class="button" id="healthCheck">Run health check</button></div><div class="panel"><h3>Data services</h3><p>Events API: <b>Configured</b></p><p>Validation: <b>Enabled</b></p><p>Local fallback: <b>Enabled</b></p><p>Audit metadata: <b>Enabled</b></p></div><div class="panel"><h3>Security baseline</h3><p>Security headers: <b>Enabled</b></p><p>Input escaping: <b>Enabled</b></p><p>Rate-limit hook: <b>Ready</b></p><p>Environment template: <b>Included</b></p></div><div class="panel"><h3>Persistence test</h3><p>Saved events and admin records use versioned local storage while the remote database connector is optional.</p><button class="ghost" id="persistenceTest">Test persistence</button></div></div></section>`;}
function integrationsView(){const sources=['All','Sportdata','Smoothcomp','Kihapp','WAKO','WKU','ICO','ISKA'];const report=state.syncReport;return `<section class="section"><div class="section-head"><div><h2>Integrations Engine</h2><small>Phase 194 • source adapters, validation and controlled synchronisation</small></div><select id="integrationSource" class="search source-select">${sources.map(x=>`<option ${state.integrationSource===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="grid integration-grid">${sources.slice(1).map((x,i)=>`<article class="panel source-card"><div class="source-head"><span>${['🏟️','🥋','📋','🌍','🏆','🇬🇧','⭐'][i]}</span><div><h3>${x}</h3><small>${i<3?'Competition platform':'Organisation feed'}</small></div></div><p>Adapter: <b>Ready</b></p><p>Validation: <b>Active</b></p><p>Last sync: <b>${report?'Just now':'Not run'}</b></p></article>`).join('')}</div><div class="panel sync-console"><h3>Synchronisation console</h3><p>Fetches demo source records, validates required fields, detects duplicates and preserves manual edits.</p><div class="actions wide"><button class="button" id="runIntegrationSync">Run controlled sync</button><button class="ghost" id="exportSync">Export sync report</button></div>${report?`<div class="sync-report"><p><b>${report.checked}</b> records checked</p><p><b>${report.accepted}</b> accepted</p><p><b>${report.duplicates}</b> duplicates blocked</p><p><b>${report.invalid}</b> invalid quarantined</p></div>`:''}</div></section>`;}

function analyticsView(){
 const a=athletes.find(x=>x.id===state.analyticsAthlete)||athletes[0];
 const scored=events.filter(e=>e.status!=='Results Available').map(e=>{const distance=parseInt(String(e.distance).replace(/[^0-9]/g,''))||500;const score=Math.max(20,100-(e.difficulty||3)*7-Math.min(28,distance/45)+(state.saved.has(e.id)?14:0)+(e.org.includes('WAKO')?8:0));return{...e,score:Math.round(score)}}).sort((x,y)=>y.score-x.score);
 const best=scored[0]||events[0];
 const formWins=(a.form.match(/W/g)||[]).length;
 const confidence=Math.min(94,58+formWins*6);
 return `<section class="section"><div class="section-head"><div><h2>AI & Analytics Platform</h2><small>Phase 195 • explainable recommendations, projections and season planning</small></div><select id="analyticsAthlete" class="search source-select">${athletes.map(x=>`<option value="${esc(x.id)}" ${x.id===a.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="stats"><div class="stat"><strong>${confidence}%</strong><span>Form confidence</span></div><div class="stat"><strong>${scored.length}</strong><span>Events analysed</span></div><div class="stat"><strong>${formWins}/5</strong><span>Recent wins</span></div><div class="stat"><strong>${best?best.score:0}</strong><span>Best fit score</span></div></div><div class="grid"><article class="panel insight-card"><h3>Recommended next event</h3><div class="recommendation-score">${best?best.score:0}</div><p><b>${esc(best?.name||'No event available')}</b></p><p>${esc(best?.flag||'')} ${esc(best?.city||'')} • ${esc(best?.org||'')}</p><p class="muted">High score reflects travel, difficulty, saved status and organisation fit. This is guidance, not a guaranteed outcome.</p><button class="button" data-open="${esc(best?.id||'')}">Review event</button></article><article class="panel"><h3>Season projection</h3><div class="analytics-bars">${[['Activity',82],['Ranking potential',76],['Travel efficiency',69],['Medal opportunity',73]].map(([n,v])=>`<label>${n}<span><i style="width:${v}%"></i></span><b>${v}</b></label>`).join('')}</div><button class="ghost" id="analyticsExport">Export analytics report</button></article><article class="panel"><h3>Competition shortlist</h3>${scored.slice(0,4).map((e,i)=>`<button class="shortlist" data-open="${esc(e.id)}"><span>${i+1}</span><div><b>${esc(e.name)}</b><small>${esc(e.org)} • ${e.score}/100 fit</small></div></button>`).join('')}</article><article class="panel"><h3>Goal planner</h3><select id="analyticsGoal" class="search">${['Ranking','Medals','Experience','Travel efficiency'].map(x=>`<option ${state.analyticsGoal===x?'selected':''}>${x}</option>`).join('')}</select><p>Current goal: <b>${esc(state.analyticsGoal)}</b></p><p>Suggested load: <b>${state.analyticsGoal==='Experience'?'4 events in 10 weeks':'3 events in 12 weeks'}</b></p><p>Recovery buffer: <b>14 days after major international events</b></p></article></div></section>`;
}
function productionView(){const r=state.productionReport;return `<section class="section"><div class="section-head"><div><h2>Production & DevOps</h2><small>Phase 196 • release safety, monitoring and deployment readiness</small></div></div><div class="stats"><div class="stat"><strong>${r?r.passed:'—'}</strong><span>Checks passed</span></div><div class="stat"><strong>${r?r.failed:'—'}</strong><span>Checks failed</span></div><div class="stat"><strong>v196</strong><span>Release channel</span></div><div class="stat"><strong>${navigator.onLine?'Online':'Offline'}</strong><span>Network</span></div></div><div class="grid"><article class="panel"><h3>Release gate</h3><p>Runs browser capability, data integrity, storage and service-worker checks.</p><button class="button" id="runProductionChecks">Run release checks</button>${r?`<div class="release-list">${r.tests.map(t=>`<p class="${t.ok?'pass':'fail'}"><b>${t.ok?'✓':'✕'}</b> ${esc(t.name)}</p>`).join('')}</div>`:''}</article><article class="panel"><h3>Observability</h3><p>API health: <b>${esc(state.apiHealth)}</b></p><p>Events loaded: <b>${events.length}</b></p><p>Duplicate IDs: <b>${duplicateIds(events)}</b></p><p>Invalid records: <b>${invalidEvents().length}</b></p><button class="ghost" id="productionHealth">Check API + metrics</button></article><article class="panel"><h3>Deployment pipeline</h3><ol class="pipeline"><li>Syntax and data validation</li><li>Function smoke tests</li><li>Asset/reference checks</li><li>Production ZIP integrity</li><li>Netlify preview deployment</li></ol><p><small>GitHub Actions workflow and local test commands are included.</small></p></article><article class="panel"><h3>Recovery controls</h3><button class="ghost" id="clearCaches">Clear app caches</button><button class="ghost" id="exportDiagnostics">Export diagnostics</button><p><small>Cache clearing does not remove saved events or custom CMS records.</small></p></article></div></section>`;}

function placement(n){return n===1?'Gold':n===2?'Silver':n===3?'Bronze':`${n}th`;}
function duplicateIds(xs){return xs.length-new Set(xs.map(x=>x.id)).size;}
function invalidEvents(){return events.filter(e=>!e.id||!e.name||!e.start||!e.end||new Date(e.start)>new Date(e.end));}
function sheet(){return `<aside class="sheet" id="sheet" aria-label="Details panel"></aside>`;}
function toast(){return state.toast?`<div class="toast" role="status">${esc(state.toast)}</div>`:'';}
function render(){const views={events:eventsView,settings:settingsView,passport:passportView,travel:travelView,club:clubView,more:moreView,backend:backendView,integrations:integrationsView,analytics:analyticsView,production:productionView,sync:syncView,replay:replayView,rankings:rankingsView,parent:parentView,admin:adminView};app.innerHTML=header()+(views[state.tab]||moreView)()+nav()+sheet()+toast();bind();}
function notify(text){state.toast=text;render();setTimeout(()=>{if(state.toast===text){state.toast='';render();}},1800);}
function openEvent(id){const e=events.find(x=>x.id===id);if(!e)return;const s=$('#sheet'),link=e.sourceUrl&&/^https:\/\//.test(e.sourceUrl)?`<p><a class="source-link" href="${esc(e.sourceUrl)}" target="_blank" rel="noopener noreferrer">View ${esc(e.source||'organiser')} listing ↗</a></p>`:'';s.innerHTML=`<button class="close" id="close">Close</button><h2>${esc(e.flag)} ${esc(e.name)}</h2><button class="button" id="sheetCalendar">📅 Add to iPhone Calendar</button><p class="muted">Import the file in Calendar and select your iCloud calendar.</p><p>${esc(e.org)} • ${esc(e.city)} • ${esc(e.venue)}</p><div class="grid"><div class="panel"><h3>Registration</h3><p>${esc(e.status)}${e.closing?' • closes '+fmt(e.closing):' • closing date TBC'}</p>${link}</div><div class="panel"><h3>Travel</h3><p>${esc(e.travel)}</p><p>${esc(e.hotel)}</p></div><div class="panel"><h3>Competition</h3><p>${fmt(e.start)}–${fmt(e.end)}</p><p>${esc(e.rule)}</p></div><div class="panel"><h3>Weekend prep</h3><p>${e.athletes} watched athletes • ${esc(e.weather)}</p></div></div>`;s.classList.add('show');$('#close').onclick=()=>s.classList.remove('show');$('#sheetCalendar').onclick=()=>addToCalendar(id);}
function openPass(id){const a=athletes.find(x=>x.id===id);if(!a)return;const s=$('#sheet');s.innerHTML=`<button class="close" id="close">Close</button><div class="qr">▦</div><h2>${esc(a.name)}</h2><p>${esc(a.club)}</p><div class="panel"><p>${esc(a.ranking)}</p><p>Licence: ${esc(a.licence)}</p><p>Insurance: ${esc(a.insurance)}</p><p>Medical: ${esc(a.medical)}</p></div>`;s.classList.add('show');$('#close').onclick=()=>s.classList.remove('show');}
function openReplay(id){const e=events.find(x=>x.id===id);if(!e)return;const s=$('#sheet');s.innerHTML=`<button class="close" id="close">Close</button><h2>🎬 ${esc(e.name)} Replay</h2><div class="replay-banner" style="--image:${esc(e.image)}"></div><div class="grid"><div class="panel"><h3>Journey</h3><p>${esc(e.travel)}</p><p>${fmt(e.start)}–${fmt(e.end)}</p></div><div class="panel"><h3>Team result</h3><p>3 medals • 7 wins • 4 personal bests</p></div><div class="panel"><h3>Media</h3><p>12 photos • 3 videos • 1 highlight reel</p></div></div>`;s.classList.add('show');$('#close').onclick=()=>s.classList.remove('show');}
function icsEscape(value){return String(value??'').replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');}
function calendarText(e){
 const end=new Date(e.end+'T12:00:00Z');end.setUTCDate(end.getUTCDate()+1);
 const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z');
 const start=e.start.replace(/-/g,''),finish=end.toISOString().slice(0,10).replace(/-/g,'');
 const details=[e.org,e.rule,e.notes,e.sourceUrl].filter(Boolean).join(' • ');
 return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//FightEye//Event Calendar//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH','BEGIN:VEVENT',`UID:${icsEscape(e.id)}@fighteye.app`,`DTSTAMP:${stamp}`,`DTSTART;VALUE=DATE:${start}`,`DTEND;VALUE=DATE:${finish}`,`SUMMARY:${icsEscape(e.name)}`,`LOCATION:${icsEscape([e.venue,e.city,e.country].filter(Boolean).join(', '))}`,`DESCRIPTION:${icsEscape(details)}`,...(e.sourceUrl&&/^https:\/\//.test(e.sourceUrl)?[`URL:${e.sourceUrl}`]:[]),'END:VEVENT','END:VCALENDAR',''].join('\r\n');
}
async function addToCalendar(id){
 const e=events.find(x=>x.id===id);if(!e)return;
 const file=new File([calendarText(e)],`${e.id}.ics`,{type:'text/calendar'});
 try{if(navigator.canShare?.({files:[file]})&&navigator.share){await navigator.share({files:[file],title:e.name});return;}}catch(error){if(error?.name==='AbortError')return;}
 download(`${e.id}.ics`,calendarText(e),'text/calendar');
 notify('Open the calendar file, then choose your iCloud calendar.');
}
function download(name,text,type='text/plain'){const b=new Blob([text],{type}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),500);}
