 $$('[data-weight-form]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const id=form.dataset.weightForm;if(!athletes.some(a=>a.id===id))return;const fd=new FormData(form),date=String(fd.get('date')||''),kg=Number(fd.get('kg'));if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>new Date().toLocaleDateString('en-CA',{timeZone:'Europe/London'})||!Number.isFinite(kg)||kg<10||kg>500)return;const previous=state.weightRecords[id];state.weightRecords[id]=[...(previous||[]).filter(r=>r.date!==date),{date,kg:Math.round(kg*10)/10,source:'Manual'}];try{saveWeightStore();state.weightError='';render();}catch{state.weightRecords[id]=previous;state.weightError='Could not save weight on this device.';render();}});
